import type { JsonValue, Subject } from "./state.js";

export interface SubmitCommand {
  type: "submit";
  /** Generated by the service with the injected id generator. */
  requestId: string;
  requesterId: string;
  subject: Subject;
  payload: JsonValue;
  tenantId?: string;
}

export interface ApproveCommand {
  type: "approve";
  requestId: string;
  actorId: string;
  comment?: string;
}

export interface RejectCommand {
  type: "reject";
  requestId: string;
  actorId: string;
  comment?: string;
}

/** Sends the request back to the requester, or back to an earlier step that ran (EC-32, EC-33). */
export interface ReturnCommand {
  type: "return";
  requestId: string;
  actorId: string;
  to: "requester" | { stepId: string };
  comment?: string;
}

/** The requester sends a returned request again, optionally with a new payload (EC-34). */
export interface ResubmitCommand {
  type: "resubmit";
  requestId: string;
  actorId: string;
  /** Omitted: the payload stays as it was. */
  payload?: JsonValue;
}

/** The requester withdraws a pending or returned request (EC-35). */
export interface WithdrawCommand {
  type: "withdraw";
  requestId: string;
  actorId: string;
  comment?: string;
}

/** Applies whatever is due at `ctx.now`: reminders, timeouts, escalation (EC-26). A system action. */
export interface TickCommand {
  type: "tick";
  requestId: string;
}

/** Hands the actor's pending task to a delegate (EC-25). */
export interface DelegateCommand {
  type: "delegate";
  requestId: string;
  actorId: string;
  taskId: string;
  toUserId: string;
  comment?: string;
}

/** Gives a blocked step to users chosen by an admin (EC-46). */
export interface ReassignStepCommand {
  type: "reassign";
  requestId: string;
  adminId: string;
  stepId: string;
  toUserIds: string[];
  comment: string;
  taskId?: never;
}

/** Moves one pending task to another user, chosen by an admin. */
export interface ReassignTaskCommand {
  type: "reassign";
  requestId: string;
  adminId: string;
  taskId: string;
  toUserId: string;
  comment: string;
  stepId?: never;
}

/** Resolves the approvers of a blocked step again, e.g. after the host fixed its data (EC-46). */
export interface RetryStepCommand {
  type: "retry";
  requestId: string;
  adminId: string;
  stepId: string;
}

/** Closes the whole request with an admin decision; every open task is cancelled (EC-18). */
export interface OverrideCommand {
  type: "override";
  requestId: string;
  adminId: string;
  decision: "approve" | "reject";
  comment: string;
}

export type Command =
  | SubmitCommand
  | ApproveCommand
  | RejectCommand
  | ReturnCommand
  | ResubmitCommand
  | WithdrawCommand
  | TickCommand
  | DelegateCommand
  | ReassignStepCommand
  | ReassignTaskCommand
  | RetryStepCommand
  | OverrideCommand;
